use std::os::unix::fs::FileTypeExt;
use std::path::Path;

pub fn get_file_type(md: &std::fs::Metadata, display_name: &str, use_mime_type: bool) -> String {
    let ft = md.file_type();
    let mut file_type = "unknown";
    if ft.is_dir() {
        file_type = "dir";
    } else if ft.is_file() {
        file_type = "file";
    } else if ft.is_symlink() {
        file_type = "symlink";
    } else {
        #[cfg(unix)]
        {
            if ft.is_block_device() {
                file_type = "block device";
            } else if ft.is_char_device() {
                file_type = "char device";
            } else if ft.is_fifo() {
                file_type = "pipe";
            } else if ft.is_socket() {
                file_type = "socket";
            }
        }
    }
    if use_mime_type {
        let guess = mime_guess::from_path(display_name);
        let mime_guess = match guess.first() {
            Some(mime_type) => mime_type.essence_str().to_string(),
            None => "unknown".to_string(),
        };
        if file_type == "file" {
            mime_guess
        } else {
            file_type.to_string()
        }
    } else {
        file_type.to_string()
    }
}

impl LsRecordBuilder {
    #[allow(clippy::too_many_arguments)]
    fn dir_entry_dict(
        &self,
        filename: &std::path::Path, // absolute path
        display_name: &str,         // file name to be displayed
        metadata: Option<&std::fs::Metadata>,
        long: bool,
        du: bool,
        signals: &Signals,
        use_mime_type: bool,
    ) -> Result<Value, ShellError> {
        #[cfg(windows)]
        if metadata.is_none() {
            return Ok(windows_helper::dir_entry_dict_windows_fallback(
                filename,
                display_name,
                self.span,
                long,
            ));
        }

        let mut record = Record::new();

        if let Some(md) = metadata {
            let file_info = FileInfo::from_metadata(filename, md, self.span);
            let span = if file_info.tag() == self.span {
                self.span
            } else {
                file_info.tag()
            };
            let effective_path = match (file_info.path().parent(), file_info.path().file_name()) {
                (Some(_), Some(name)) => file_info.listing_parent().join(name),
                _ => file_info.path().to_path_buf(),
            };

            record.push("name", Value::string(display_name, span));
            let file_type = get_file_type(md, display_name, use_mime_type);
            record.push("type", Value::string(file_type.clone(), span));

            if long {
                record.push(
                    "target",
                    if md.file_type().is_symlink() {
                        if let Ok(path_to_link) = effective_path.read_link() {
                            Value::string(path_to_link.to_string_lossy(), span)
                        } else {
                            Value::string("Could not obtain target file's path", span)
                        }
                    } else {
                        Value::nothing(span)
                    },
                );
                push_long_metadata_fields(&mut record, md, span);
            }

            record.push(
                "size",
                if md.is_dir() {
                    if du {
                        let params = DirBuilder::new(Span::new(0, 2), None, false, None, false);
                        let params = DirBuilder::new(
                            Span::new(0, 2),
                            params.min,
                            params.deref,
                            None,
                            params.all,
                        );
                        let dir_size = directory_apparent_size(
                            &effective_path,
                            &params,
                            span,
                            signals,
                        )?;
                        let dir_size = dir_size.saturating_sub(params.min.unwrap_or(0));
                        Value::filesize(dir_size as i64, span)
                    } else {
                        Value::filesize(file_info.size() as i64, span)
                    }
                } else if md.is_file() {
                    Value::filesize(file_info.size() as i64, span)
                } else if md.file_type().is_symlink() {
                    Value::filesize(file_info.size() as i64, span)
                } else if file_type == "pipe"
                    || file_type == "socket"
                    || file_type == "char device"
                    || file_type == "block device"
                {
                    Value::filesize(0, span)
                } else {
                    Value::nothing(span)
                },
            );

            push_timestamp_fields(&mut record, md, span, long);
        } else {
            record.push("name", Value::string(display_name, self.span));
            record.push("type", Value::nothing(self.span));
            record.push("size", Value::nothing(self.span));
            if long {
                record.push("created", Value::nothing(self.span));
                record.push("accessed", Value::nothing(self.span));
            }
            record.push("modified", Value::nothing(self.span));
        }

        Ok(Value::record(record, self.span))
    }
}

