        let m = if deref {
            std::fs::metadata(&path)
        } else {
            std::fs::symlink_metadata(&path)
        };

        match m {
            Ok(d) => {
                let block_size = file_real_size_fast(&path, &d).ok();
                let expansion = PathExpansion::for_parent_light(&path);

                Ok(FileInfo {
                    path,
                    blocks: block_size,
                    size: d.len(),
                    tag,
                    expansion,
                })
            }
            Err(e) => Err(e.into()),
        }
    }

