#[cfg(windows)]
use omnipath::WinPathExt;
use std::io;
use std::path::{Path, PathBuf};

use super::dots::{expand_dots, expand_ndots};
use super::helpers::HomeContext;
use super::tilde::expand_tilde;

// Join a path relative to another path. Paths starting with tilde are considered as absolute.
fn join_path_relative<P, Q>(path: P, relative_to: Q, expand_tilde: bool) -> PathBuf
where
    P: AsRef<Path>,
    Q: AsRef<Path>,
{
    let path = path.as_ref();
    let relative_to = relative_to.as_ref();

    if path == Path::new(".") {
        // Joining a Path with '.' appends a '.' at the end, making the prompt
        // more ugly - so we don't do anything, which should result in an equal
        // path on all supported systems.
        relative_to.into()
    } else if path.to_string_lossy().as_ref().starts_with('~') && expand_tilde {
        // do not end up with "/some/path/~" or "/some/path/~user"
        path.into()
    } else {
        relative_to.join(path)
    }
}

fn canonicalize(path: impl AsRef<Path>) -> io::Result<PathBuf> {
    let path = expand_tilde(path);
    let path = expand_ndots(path);
    canonicalize_path(&path)
}

#[cfg(windows)]
fn canonicalize_path(path: &std::path::Path) -> std::io::Result<std::path::PathBuf> {
    path.canonicalize()?.to_winuser_path()
}

#[cfg(not(windows))]
fn canonicalize_path(path: &std::path::Path) -> std::io::Result<std::path::PathBuf> {
    path.canonicalize()
        }
    }
}

#[derive(Debug, Clone)]
pub struct PathExpansion {
    relative_to: PathBuf,
    expand_tilde: bool,
    home: HomeContext,
}

impl PathExpansion {
    pub fn for_parent(path: &Path) -> Self {
        let relative_to = path
            .parent()
            .map(|parent| parent.to_path_buf())
            .unwrap_or_else(|| path.to_path_buf());
        let home = HomeContext::current();
        let expand_tilde = home.home_path().is_some();
        Self {
            relative_to,
            expand_tilde,
            home,
        }
    }

    pub fn for_parent_light(path: &Path) -> Self {
        let relative_to = path
            .parent()
            .map(|parent| parent.to_path_buf())
            .unwrap_or_else(|| path.to_path_buf());
        Self {
            relative_to,
            expand_tilde: true,
            home: HomeContext::empty(),
        }
    }

    pub fn relative_to(&self) -> &Path {
        &self.relative_to
    }

    pub fn expand_tilde(&self) -> bool {
        self.expand_tilde
    }

    pub fn expand(&self, path: impl AsRef<Path>) -> PathBuf {
        let expand_tilde = self.expand_tilde && self.home.home_path().is_some();
        expand_path_with(path, &self.relative_to, expand_tilde)
    }
}

